import itertools, sys

def hyperedges(n):
    edges=[]
    for i in range(n):
        for j in range(i+1,n):
            for k in range(n):
                for l in range(k+1,n):
                    edges.append(((i,k),(j,k),(j,l)))
    return edges

def is_colorable(n, colors, time_limit=60):
    cells=[(i,j) for i in range(n) for j in range(n)]
    idx={c:i for i,c in enumerate(cells)}
    edges=hyperedges(n)
    # precompute edges by max cell index for incremental check
    edges_by_last=[[] for _ in range(len(cells))]
    for e in edges:
        m=max(idx[v] for v in e)
        edges_by_last[m].append(e)
    assign=[-1]*len(cells)
    # symmetry: first cell 0, second? We can break color permutation by requiring first occurrence order.
    # Use recursive with forward checking.
    sys.setrecursionlimit(10000)
    def ok(pos, val):
        assign[pos]=val
        for e in edges_by_last[pos]:
            a,b,c=e
            vals=[assign[idx[a]],assign[idx[b]],assign[idx[c]]]
            if -1 not in vals and len(set(vals))==1:
                assign[pos]=-1
                return False
        return True
    def dfs(pos, used):
        if pos==len(cells): return True
        # color symmetry: can use colors 0..used, and used+1 if used<colors-1
        maxc=min(used+1, colors-1)
        # order colors: try existing first
        for c in range(maxc+1):
            if ok(pos,c):
                newused=max(used,c)
                if dfs(pos+1,newused): return True
                assign[pos]=-1
        return False
    # fix first cell 0
    assign[0]=0
    return dfs(1,0)

for n in range(2,6):
    for k in range(1,5):
        print(n,k,is_colorable(n,k))
"}

{"operation":"run_python","code":"from itertools import combinations

def simulate(adj, N):
    # adj list of bitsets
    alive = [True]*N
    deg = [bin(adj[i]).count('1') for i in range(N)]
    # t=0..N-1
    for t in range(N):
        rem = [i for i in range(N) if alive[i] and deg[i]==t]
        if not rem:
            continue
        for v in rem:
            alive[v]=False
        for v in rem:
            # update degrees of alive neighbors
            nb = adj[v]
            for u in range(N):
                if (nb>>u)&1 and alive[u]:
                    deg[u]-=1
    return sum(alive)

def possible(N):
    M=N*(N-1)//2
    res=set()
    for mask in range(1<<M):
        adj=[0]*N
        idx=0
        for i in range(N):
            for j in range(i+1,N):
                if (mask>>idx)&1:
                    adj[i]|=1<<j
                    adj[j]|=1<<i
                idx+=1
        res.add(simulate(adj,N))
    return sorted(res)

for N in range(1,7):
    print(N, possible(N))
