from itertools import combinations

n = 15
def readings_injective(S):
    seen = {}
    for mid in range(n):
        T = frozenset([(mid-1) % n, mid, (mid+1) % n])
        r = frozenset(T & S)
        if r in seen:
            return False, (seen[r], mid)
        seen[r] = mid
    return True, None

best = {}
for k in range(0, 16):
    found = None
    for c in combinations(range(n), k):
        ok, _ = readings_injective(set(c))
        if ok:
            found = [x+1 for x in c]
            break
    best[k] = found
    print(k, "sufficient" if found else "NOT sufficient")

print("minimum detectors =", min(k for k in best if best[k]))
print("example set (1-indexed):", best[min(k for k in best if best[k])])
"}

