from itertools import combinations
n=15
def inj(S):
    seen={}
    for mid in range(n):
        T=frozenset([(mid-1)%n,mid,(mid+1)%n])
        r=frozenset(T&S)
        if r in seen: return False
        seen[r]=mid
    return True
for k in range(16):
    f=None
    for c in combinations(range(n),k):
        if inj(set(c)):
            f=[x+1 for x in c]; break
    print(k, bool(f), f)
